// Embed the two approved-for-audition cuts so double-click previews work offline.
window.fireworkSample = (() => {
  const clips = ['', ''];
  const swapClips = document.currentScript.hasAttribute('data-swap-clips');
  const slowShow = document.currentScript.hasAttribute('data-slow-show');
  const tempo = slowShow ? .88 : 1;
  const buffers = [];
  let loading;
  const last = [-Infinity, -Infinity];
  function prepare(ctx) {
    if (!ctx || loading) return;
    loading = Promise.all(clips.map(async (clip, i) => {
      const bytes = Uint8Array.from(atob(clip), ch => ch.charCodeAt(0));
      buffers[i] = await ctx.decodeAudioData(bytes.buffer);
    }));
  }
  let reverbImpulse;
  function addFinalTail(ctx, source, now, duration) {
    if (!reverbImpulse) {
      reverbImpulse = ctx.createBuffer(1, Math.ceil(ctx.sampleRate * 1.4), ctx.sampleRate);
      const impulse = reverbImpulse.getChannelData(0);
      for (let k = 0; k < impulse.length; k++) {
        impulse[k] = (Math.random() * 2 - 1) * Math.pow(1 - k / impulse.length, 2.5);
      }
    }
    const reverb = ctx.createConvolver(), warmth = ctx.createBiquadFilter(), wet = ctx.createGain();
    reverb.buffer = reverbImpulse;
    warmth.type = 'lowpass';
    warmth.frequency.value = 2300;
    wet.gain.setValueAtTime(.42, now);
    wet.gain.setValueAtTime(.42, now + duration);
    wet.gain.exponentialRampToValueAtTime(.001, now + duration + 1.4);
    source.connect(reverb).connect(warmth).connect(wet).connect(ctx.destination);
  }
  function play(ctx, i, finalCue = false) {
    const buffer = buffers[swapClips ? 1 - i : i];
    if (!ctx || ctx.state !== 'running' || !buffer || document.hidden) return;
    const now = ctx.currentTime;
    if (!slowShow && now - last[i] < .48 / tempo) return;
    last[i] = now;
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.playbackRate.value = slowShow && i === 1 ? .8 : tempo;
    if (slowShow) {
      const duration = i === 0 ? Math.min(buffer.duration / tempo, 1 / tempo) : buffer.duration / source.playbackRate.value;
      const envelope = ctx.createGain();
      envelope.gain.setValueAtTime(1, now);
      envelope.gain.setValueAtTime(1, now + duration - (i === 0 ? .18 : .06));
      envelope.gain.linearRampToValueAtTime(0, now + duration);
      source.connect(envelope).connect(ctx.destination);
      if (i === 1 && finalCue) addFinalTail(ctx, source, now, duration);
      source.start(now);
      source.stop(now + duration);
      return now + duration + (i === 1 && finalCue ? 1.4 : 0);
    } else {
      source.connect(ctx.destination);
      source.start();
    }
  }
  return {prepare, play, tempo, syncGroups: slowShow};
})();
